import{_ as a}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as t,o as r,af as o}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const b=JSON.parse('{"title":"火山方舟教程","description":"打开方舟控制台拿 API Key，按官方文档完成第一次调用，或安装官方 CLI。不编造 Base URL。","frontmatter":{"title":"火山方舟教程","description":"打开方舟控制台拿 API Key，按官方文档完成第一次调用，或安装官方 CLI。不编造 Base URL。","domain":"product","tags":["api"],"role":"tutorial"},"headers":[],"relativePath":"zh/products/volcengine-ark/volcengine-ark.md","filePath":"zh/products/volcengine-ark/volcengine-ark.md","lastUpdated":1787110548000}'),i={name:"zh/products/volcengine-ark/volcengine-ark.md"};function n(l,e,d,s,h,c){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="火山方舟教程" tabindex="-1">火山方舟教程 <a class="header-anchor" href="#火山方舟教程" aria-label="Permalink to &quot;火山方舟教程&quot;">​</a></h1><blockquote><p>产品页：<a href="https://www.volcengine.com/product/ark" target="_blank" rel="noreferrer">volcengine.com/product/ark</a>。第一次 HTTP 调用以官方 <a href="https://www.volcengine.com/docs/82379/1399008" target="_blank" rel="noreferrer">快速入门</a> 为准。本页不编造 endpoint 或模型 ID。</p></blockquote><h2 id="目标与非目标" tabindex="-1">目标与非目标 <a class="header-anchor" href="#目标与非目标" aria-label="Permalink to &quot;目标与非目标&quot;">​</a></h2><p><strong>写给谁：</strong> 要接豆包大模型的前端 / Node 工程师。</p><p><strong>你会完成：</strong> 打开 API Key 页；知道文档树在哪；能装官方 CLI。</p><p><strong>不会做：</strong> 把豆包 App 当控制台、把 Trae 当方舟、抄一份过期的模型全表。</p><h2 id="先决条件" tabindex="-1">先决条件 <a class="header-anchor" href="#先决条件" aria-label="Permalink to &quot;先决条件&quot;">​</a></h2><ul><li>一个火山引擎账号。</li><li>需要 CLI 时：本机有 npm。</li></ul><h2 id="_15-分钟内打开" tabindex="-1">15 分钟内打开 <a class="header-anchor" href="#_15-分钟内打开" aria-label="Permalink to &quot;15 分钟内打开&quot;">​</a></h2><h3 id="_1-拿-api-key" tabindex="-1">1. 拿 API Key <a class="header-anchor" href="#_1-拿-api-key" aria-label="Permalink to &quot;1. 拿 API Key&quot;">​</a></h3><p>打开官方入口 <a href="https://ark.volcengine.com/region:cn-beijing/apiKey" target="_blank" rel="noreferrer">获取 API KEY</a>（火山引擎首页「通过火山方舟开启一站式大模型服务」旁）。</p><p>Key 的创建步骤、项目空间切换，以文档中心「获取 API Key 并配置」为准。本页不复述 SPA 里看不见的点击路径。</p><h3 id="_2-第一次调用走官方页" tabindex="-1">2. 第一次调用走官方页 <a class="header-anchor" href="#_2-第一次调用走官方页" aria-label="Permalink to &quot;2. 第一次调用走官方页&quot;">​</a></h3><p>打开 <a href="https://www.volcengine.com/docs/82379/1399008" target="_blank" rel="noreferrer">快速入门</a>（最近更新 2026.01.30）。选模型打开 <a href="https://www.volcengine.com/docs/82379" target="_blank" rel="noreferrer">模型列表</a> 侧栏「模型列表」，不要从本站抄 ID。</p> 无 JS 环境下快速入门正文为空。不要用第三方博客里的 `base_url` 填这里。 <h3 id="_3-可选-装方舟-cli" tabindex="-1">3. 可选：装方舟 CLI <a class="header-anchor" href="#_3-可选-装方舟-cli" aria-label="Permalink to &quot;3. 可选：装方舟 CLI&quot;">​</a></h3><p>火山引擎首页原文：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @volcengine/ark-cli@latest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -g</span></span></code></pre></div><p>产品页原文：「通过火山方舟官方命令行工具，一行命令完成认证、模型调用与资源管理」「方舟 CLI 上线，支持 Claude Code、Cursor、TRAE 等」。</p><p>CLI 子命令以官方「使用指南」为准，本页不编 <code>ark login</code> 之类未核对的 flag。</p><h2 id="官方能力-按出处分组" tabindex="-1">官方能力（按出处分组） <a class="header-anchor" href="#官方能力-按出处分组" aria-label="Permalink to &quot;官方能力（按出处分组）&quot;">​</a></h2><p>文档侧栏（2026-08-19 打开产品简介 / 快速入门页）可见这些一级分组：</p><table tabindex="0"><thead><tr><th>分组</th><th>里面有什么（侧栏原文）</th><th>本站</th></tr></thead><tbody><tr><td>开始使用</td><td>产品简介、快速入门、模型列表、模型价格、豆包大模型1.8</td><td>本页链出去</td></tr><tr><td>模型调用</td><td>文本生成、多模态理解、图片生成、视频生成、领域模型、工具调用</td><td>官方页</td></tr><tr><td>进阶使用</td><td>接入三方工具、使用 Responses API</td><td><a href="./volcengine-ark-cookbook.html">Cookbook</a></td></tr><tr><td>部署方式</td><td>常规 / 低延迟在线推理、模型单元、批量推理</td><td>地图一行</td></tr><tr><td>高级能力</td><td>模型精调及最佳实践</td><td>地图一行</td></tr><tr><td>Coding Plan</td><td>套餐概览、快速开始、接入 AI 编程工具</td><td>Cookbook</td></tr></tbody></table><p>产品页另有安全能力（链路全加密、数据高保密、环境强隔离、操作可审计）。不当营销句展开。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li>接到 Claude Code / Cursor / Trae：<a href="./volcengine-ark-cookbook.html">Cookbook</a></li><li>回查 URL 与套餐原文：<a href="./volcengine-ark-cheatsheet.html">速查</a></li><li>模型内部：<a href="/zh/tech/fundamentals/LLM.html">Learn LLM</a></li></ul>',26)])])}const m=a(i,[["render",n]]);export{b as __pageData,m as default};
